stage_a_raw:
{
  "decisions": [
    {
      "decision": "domain_of_flow_variables",
      "evidence": "Demand of Each Retail Store (in units) ... Supply Capacity of Each Distribution Center (in units)",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "\"fulfill their demands\" / \"Demand of Each Retail Store (in units)\"",
      "options": [
        "sum_i x[i,j] == demand[j]",
        "sum_i x[i,j] >= demand[j]"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "sum_i x[i,j] == demand[j]"
    },
    {
      "decision": "capacity_constraint_form",
      "evidence": "\"Supply Capacity of Each Distribution Center (in units)\"",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] <= capacity[i] (no linking to y[i])"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "objective_components",
      "evidence": "\"minimize the total cost involved, which includes the initial opening costs of the distribution centers and the ongoing transportation costs\"",
      "options": [
        "minimize sum_i open_cost[i]*y[i] + sum_ij trans_cost[i,j]*x[i,j]",
        "minimize sum_ij trans_cost[i,j]*x[i,j] only"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "minimize sum_i open_cost[i]*y[i] + sum_ij trans_cost[i,j]*x[i,j]"
    },
    {
      "decision": "transport_cost_orientation",
      "evidence": "\"Transportation Cost Per Unit from Each Distribution Center to Retail Stores\"",
      "options": [
        "trans_cost indexed [center][store] as given",
        "trans_cost indexed [store][center] (transposed)"
      ],
      "plausibility": [
        0.98,
        0.02
      ],
      "majority_option": "trans_cost indexed [center][store] as given"
    },
    {
      "decision": "opening_variable_domain",
      "evidence": "\"selecting the right combination of distribution centers to open\"",
      "options": [
        "Binary y[i]",
        "NonNegativeReals y[i] in [0,1]"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "Binary y[i]"
    }
  ]
}
